def _digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _builtin_entries() -> list[dict[str, Any]]:
    rows = [{"slug": slug, "name": name, "description": description,
             "reason": reason, "dependency": dependency, "market": "china_a", "entry": "SignalEngine"}
            for slug, name, description, reason, dependency in _BUILTINS]
    rows.extend({"slug": "options-strategy-" + slug, "name": name,
        "description": "原生期权合约腿示例，使用历史波动率和Black-Scholes合成定价。",
        "reason": "期权合约腿与合成定价不适用于普通A股选股及股票回测。",
        "dependency": None, "market": "options", "entry": entry}
        for slug, name, entry in _OPTIONS)
    return rows


def _builtin(slug: str) -> dict[str, Any]:
    row = next((row for row in _builtin_entries() if row["slug"] == slug), None)
    if row is None:
        raise HTTPException(404, "Strategy not found")
    return row


def _builtin_code(row: dict[str, Any], parameters: dict[str, int] | None = None) -> tuple[bytes, bytes, str]:
    slug = row["slug"]
    skill = "options-strategy" if slug.startswith("options-strategy-") else slug
    relative = f"src/skills/{skill}/" + ("SKILL.md" if skill == "ml-strategy" else "example_signal_engine.py")
    raw = (_AGENT / relative).read_bytes()
    if skill == "multi-factor":
        from src.api.mona_backtest_settings import _template_source
        original, code = _template_source(parameters)
        return original, code, relative
    if parameters:
        raise HTTPException(422, "This strategy's parameters are read-only; create a modified strategy with AI")
    if skill == "ml-strategy":
        match = re.search(r"```python\s*\n(.*?)\n```", raw.decode("utf-8"), re.S)
        if match is None or "class SignalEngine:" not in match[1]:
            raise HTTPException(503, "Native ML example boundary changed")
        code = (match[1] + "\n").encode("utf-8")
    else:
        tree = ast.parse(raw.decode("utf-8"))
        code = raw
        for index, node in enumerate(tree.body):
            if (isinstance(node, ast.If) and isinstance(node.test, ast.Compare)
                and isinstance(node.test.left, ast.Name) and node.test.left.id == "__name__"
                and len(node.test.comparators) == 1
                and isinstance(node.test.comparators[0], ast.Constant)
                and node.test.comparators[0].value == "__main__"):
                if index != len(tree.body) - 1:
                    raise HTTPException(503, "Native example self-test boundary changed")
                code = b"".join(raw.splitlines(keepends=True)[:node.lineno - 1])
                break
    if row["entry"] != "SignalEngine":
        code += ("\nSignalEngine = " + row["entry"] + "\n").encode("utf-8")
    return raw, code, relative


