def strategy_tool_receipt(tool: str, raw: str) -> dict[str, Any] | None:
    """Keep minimal concrete write/registration evidence before SSE truncation."""
    if os.environ.get("VIBE_TRADING_HOSTED") != "1" or tool not in {"write_file", "sdm_register"}:
        return None
    try:
        payload = json.loads(raw)
        if payload.get("status") != "ok":
            return None
        if tool == "sdm_register":
            artifact = payload.get("artifact")
            if isinstance(artifact, dict) and artifact.get("type") == "strategy" and re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", str(artifact.get("id", ""))):
                return {"kind": "registration", "artifact_id": artifact["id"]}
            return None
        from src.api.mona_reads import _safe_private_regular_file
        path = _safe_private_regular_file(Path(payload["path"]), get_runtime_root().resolve())
        if path is not None and path.name in {"config.json", "signal_engine.py"} and path.stat().st_size <= 1024 * 1024:
            return {"kind": "file", "path": str(path), "sha256": _digest(path.read_bytes())}
    except (KeyError, TypeError, ValueError, OSError, AttributeError):
        return None
    return None


