    from src.api.mona_backtest_settings import _parameters
    if strategy_id.startswith("builtin:"):
        row = _builtin(strategy_id.split(":", 1)[1])
        raw, code, relative = _builtin_code(row)
        version = _digest(code + b"\0" + row["entry"].encode())
        reason = row["reason"]
        if not reason and row["dependency"] and importlib.util.find_spec(row["dependency"]) is None:
            reason = "缺少策略所需依赖：" + row["dependency"]
