                {"label": "来源摘要", "value": _digest(raw)}]}
    artifact = _custom_asset(strategy_id)
    from src.api.mona_operations import _resolve_run
    linked, config = _execution(strategy_id)
    reason = None if linked else "尚未关联可执行策略代码与配置，请用AI补全。"
    parameters = []
    market = "china_a" if artifact.universe.lower() in {"equity_cn", "china_a", "csi300", "a股", "中国a股"} else "multi_asset"
    if linked:
        source = (_resolve_run(linked["run_id"]) / "code/signal_engine.py").read_text(encoding="utf-8")
