def strategy_catalog(limit: int = 100, offset: int = 0, q: str = "", source: str | None = None,
                     market: str = "all") -> dict[str, Any]:
    if source not in (None, "builtin", "custom") or market not in ("all", "china_a"):
        raise HTTPException(422, "Invalid strategy filter")
    identities = ["builtin:" + row["slug"] for row in _builtin_entries()]
    identities.extend("sdm:" + artifact.id for artifact in _artifacts())
    rows = [strategy_detail(identity) for identity in identities]
    rows = [row for row in rows if (source is None or row["source"] == source)
            and (market == "all" or row["market"] == market)
            and (not q or q.casefold() in (row["name"] + " " + row["description"]).casefold())]
    return {"items": rows[offset:offset + limit], "total": len(rows), "limit": limit, "offset": offset}


def _daily_cutoff(now: datetime | None = None) -> str:
    """Use the same 15:00 Shanghai completion boundary as native daily research."""
    current = now or datetime.now(ZoneInfo("Asia/Shanghai"))
    current = current.astimezone(ZoneInfo("Asia/Shanghai"))
    day = current.date() if current.hour * 60 + current.minute >= 900 else current.date() - timedelta(days=1)
    return day.isoformat()


def validate_strategy_operation(payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    from src.api.mona_backtest_settings import validate_settings
    if set(payload) - {"operation", "strategy_id", "strategy_version", "settings", "strategy_parameters"}:
        raise HTTPException(422, "Strategy operation fields do not match the contract")
    strategy = strategy_detail(payload.get("strategy_id"))
    if not _VERSION.fullmatch(str(payload.get("strategy_version", ""))) or payload["strategy_version"] != strategy["version"]:
        raise HTTPException(409, "Strategy version changed; read the current version before running")
    if not strategy["can_scan" if payload["operation"] == "strategy_scan" else "can_backtest"]:
        raise HTTPException(422, strategy["unavailable_reason"])
    settings = validate_settings(payload.get("settings", {}))
    if payload["operation"] == "strategy_scan":
        if settings.get("interval", strategy["interval"]) != "1D":
            raise HTTPException(422, "Current strategy scans support daily bars only")
        cutoff = _daily_cutoff()
        settings.setdefault("end_date", cutoff)
        if settings["end_date"] > cutoff:
            raise HTTPException(422, "Scan cutoff is after the latest complete daily-bar boundary")
    parameters = payload.get("strategy_parameters", {})
    editable = {row["name"] for row in strategy["parameters"] if row["editable"]}
    if (not isinstance(parameters, dict) or set(parameters) - editable
            or any(type(value) is not int or value < 1 for value in parameters.values())):
        raise HTTPException(422, "Only supported positive integer strategy parameters may be set")
    clean = {"operation": payload["operation"], "strategy_id": strategy["strategy_id"],
        "strategy_version": strategy["version"], "settings": settings, "strategy_parameters": parameters}
    return clean, {"strategy_id": strategy["strategy_id"], "strategy_version": strategy["version"]}


def prepare_operation(payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    from src.api.mona_backtest_settings import _effective, _read_config, backtest_defaults
    from src.api.mona_operations import (
        _copy_versioned_run,
        _is_link,
        _remove_versioned_run,
        _resolve_run,
        _run_code_sha256,
    )
    strategy = strategy_detail(payload["strategy_id"])
    if strategy["version"] != payload["strategy_version"]:
        raise HTTPException(409, "Strategy version changed")
    root = get_runs_dir()
    if _is_link(root):
        raise HTTPException(422, "Native runs root is invalid")
    root.mkdir(parents=True, exist_ok=True)
    if root.resolve() != get_runtime_root().resolve() / "runs":
        raise HTTPException(422, "Native runs root escapes private state")
    source_meta = {"strategy_id": strategy["strategy_id"], "strategy_version": strategy["version"],
        "strategy_name": strategy["name"]}
    if strategy["source"] == "builtin":
        run_id = "mona-" + uuid.uuid4().hex
        run_dir = root / run_id
        run_dir.mkdir()
        try:
            row = _builtin(strategy["strategy_id"].split(":", 1)[1])
            raw, code, relative = _builtin_code(row, payload.get("strategy_parameters"))
            (run_dir / "code").mkdir()
            (run_dir / "code/signal_engine.py").write_bytes(code)
            config = backtest_defaults()["defaults"]
            if row["slug"] == "fundamental-filter":
                config["fundamental_fields"] = {"income": ["total_revenue", "n_income"],
                    "balancesheet": ["total_hldr_eqy_exc_min_int"], "fina_indicator": ["roe", "debt_to_assets"]}
            source_meta.update(source_path=relative, source_sha256=_digest(raw),
                data_requirements=_requirements(row, payload.get("strategy_parameters", {})))
        except Exception:
            _remove_versioned_run(run_id, run_dir)
            raise
    else:
        source_run = strategy["linked_run"]["run_id"]
        run_id, run_dir = _copy_versioned_run(source_run, _resolve_run(source_run))
        config = _read_config(run_dir)
        source_meta["input_run_id"] = source_run
        artifact = _custom_asset(strategy["strategy_id"])
        source_meta["data_requirements"] = {"columns": list(artifact.columns_required),
            "event_score": "event_score" in artifact.columns_required,
            "min_bars": max(1, int(config.get("warmup_bars") or 0) + 1)}
    try:
        effective = _effective({**config, **payload["settings"]})
        final_config = {**config, **effective}
        config_raw = (json.dumps(final_config, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode()
        (run_dir / "config.json").write_bytes(config_raw)
        parameters = payload.get("strategy_parameters", {})
        refs = {**source_meta, "run_id": run_id, "effective_config": effective,
            "config_sha256": _digest(config_raw), "code_sha256": _run_code_sha256(run_dir),
            "strategy_parameters": parameters}
        (run_dir / "mona_strategy_source.json").write_text(json.dumps(refs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        worker = {**payload, "run_id": run_id, "_run_dir": str(run_dir)}
        return worker, {"operation": payload["operation"], **refs}, refs
    except Exception:
        _remove_versioned_run(run_id, run_dir)
        raise


def execute_scan(payload: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    from src.api.mona_operations import _read_bounded, _resolve_run
    from src.core.runner import Runner
    run_dir = _resolve_run(payload["run_id"])
    spec = {"defaults": {"required": ["strategy_scan"]}, "artifacts": {
        "strategy_scan": {"path": "artifacts/strategy_scan.json", "required": True}}}
    try:
        result = Runner(timeout=300, artifacts_spec=spec).execute(
            _AGENT / "backtest/strategy_scan.py", run_dir, cwd=_AGENT, cli_args=[str(run_dir)])
    except subprocess.TimeoutExpired:
        return json.dumps({"status": "error", "kind": "strategy_scan", "error_code": "strategy_scan_timeout"}), {}
    if not result.success:
        return json.dumps({"status": "error", "kind": "strategy_scan", "error_code": "strategy_scan_failed",
            "exit_code": result.exit_code}), {}
    path = run_dir / "artifacts/strategy_scan.json"
    parsed = json.loads(_read_bounded(path, 2 * 1024 * 1024, "strategy scan"))
    if parsed.get("strategy_id") != payload["strategy_id"] or parsed.get("strategy_version") != payload["strategy_version"]:
        raise ValueError("strategy_scan_source_mismatch")
    return json.dumps(parsed, ensure_ascii=False, allow_nan=False), {"run_id": run_dir.name}


def history(limit: int = 50, offset: int = 0, strategy_id: str | None = None,
            operation: str | None = None) -> dict[str, Any]:
    from src.api.mona_operations import _OperationStore
    if strategy_id is not None and (not _ID.fullmatch(strategy_id) or ".." in strategy_id):
        raise HTTPException(422, "Invalid strategy identity")
    store = _OperationStore()
    where = "operation IN ('strategy_scan','backtest') AND json_extract(references_json,'$.strategy_id') IS NOT NULL"
    values: list[Any] = []
    if operation is not None:
        if operation not in {"strategy_scan", "backtest"}:
            raise HTTPException(422, "Invalid strategy history operation")
        where += " AND operation=?"
        values.append(operation)
    if strategy_id is not None:
        where += " AND json_extract(references_json,'$.strategy_id')=?"
        values.append(strategy_id)
    with closing(store._connect()) as connection:
        total = connection.execute("SELECT COUNT(*) FROM operations WHERE " + where, values).fetchone()[0]
        rows = connection.execute("SELECT operation_id,operation,status,payload_json,references_json,source_json,"
            "error_category,created_at,updated_at FROM operations WHERE " + where
            + " ORDER BY created_at DESC LIMIT ? OFFSET ?", [*values, limit, offset]).fetchall()
    return {"items": [store._decode(row) for row in rows], "total": total, "limit": limit, "offset": offset}


def creation_context(config: dict[str, Any]) -> str:
    if config.get("mona_strategy_creation") is not True:
        return ""
    origin = config.get("mona_native_research") or {}
    detail = strategy_detail(origin["strategy_id"]) if origin.get("strategy_id", "").startswith(("builtin:", "sdm:")) else None
    source = ""
    if detail and detail["source"] == "builtin":
        row = _builtin(detail["strategy_id"].split(":", 1)[1])
        _raw, code, relative = _builtin_code(row)
        source = "\nOriginal bundled strategy (read only): " + str((_AGENT / relative).resolve()) + "\n" + code.decode("utf-8")
    elif detail and detail.get("linked_run"):
        source = "\nOriginal strategy run (read only): " + str((get_runs_dir() / detail["linked_run"]["run_id"]).resolve())
    return ("\n\n<strategy_creation_context>\nThe user is creating or changing a reusable strategy. "
        "Load strategy-generate and appropriate native factor/model skills. Clarify only essential missing requirements. "
        "Create config.json and code/signal_engine.py in this attempt's NEW run directory using write_file; "
        "never edit the source strategy. Keep the native SignalEngine() / generate(data_map) interface and real data requirements. "
        "Use sdm_register for a strategy only after actual code/config exist, preserving the source relation "
        "and declaring every extra input column in columns_required. "
        "A text answer is not a saved executable strategy. Backtest only if the user's request includes it; "
        "never invent or copy performance. Arbitrary rule changes use fresh code and a new strategy, not restricted adapt_strategy. "
        "Successful strategy files are validated and registered by the service after the attempt. "
        "This context authorizes no trading order.\n" + json.dumps({"origin": origin}, ensure_ascii=False)
        + source + "\n</strategy_creation_context>")


def finish_creation(session, attempt, result: dict[str, Any]) -> list[dict[str, Any]]:
    """Register only files written successfully by this completed creation attempt."""
    if session.config.get("mona_strategy_creation") is not True or result.get("status") != "success":
        return []
    from backtest.runner import BacktestConfigSchema, _validate_signal_engine_source
    from src.api.mona_backtest_settings import _read_config
    from src.api.mona_operations import _copy_versioned_run, _resolve_run, _run_code_sha256
    from src.strategy_store.models import Artifact, ArtifactType
    trail = result.get("tool_trail", [])
    successful = [row for row in trail if row.get("status") == "ok" and row.get("call_id")]
    if not isinstance(result.get("run_dir"), str):
        return []
    current = Path(result["run_dir"]).resolve(strict=True)
    writes = {}
    registrations = []
    for row in successful:
        receipt = row.get("strategy_receipt") or {}
        if row.get("tool") == "sdm_register" and receipt.get("kind") == "registration":
            registrations.append(_custom_asset("sdm:" + str(receipt.get("artifact_id", ""))))
        if row.get("tool") == "write_file" and receipt.get("kind") == "file":
            path = Path(receipt["path"]).resolve(strict=True)
            if path.is_relative_to(current) and _digest(path.read_bytes()) == receipt.get("sha256"):
                writes[path] = receipt["sha256"]
    outputs = []
    paths = {path.parent.parent for path in writes if path.name == "signal_engine.py" and path.parent.name == "code"}
    for source in paths:
        if source / "config.json" not in writes:
            continue
        if source.parent != get_runs_dir().resolve():
            continue
        source = _resolve_run(source.name)
        config = _read_config(source)
        BacktestConfigSchema.model_validate(config)
        _validate_signal_engine_source(source / "code/signal_engine.py")
        _run_code_sha256(source)
        new_id, snapshot = _copy_versioned_run(source.name, source)
        origin = session.config.get("mona_native_research") or {}
        parent = origin.get("strategy_id")
        registered = next((artifact for artifact in registrations
            if artifact.signal_engine_path and Path(artifact.signal_engine_path).resolve() == source / "code/signal_engine.py"), None)
        if registered is not None:
            updated = _store().update_artifact(replace(registered, run_dir=str(snapshot),
                signal_engine_path=str(snapshot / "code/signal_engine.py"), derived_from=parent))
            if updated is None:
                raise ValueError("registered_strategy_disappeared")
            identifier = registered.id
        else:
            name = session.title.strip() or "自定义策略"
            if any(artifact.name == name and artifact.universe == "equity_cn" for artifact in _artifacts()):
                name += " · " + attempt.attempt_id[:8]
            identifier = _store().register_artifact(Artifact(id="", type=ArtifactType.STRATEGY,
                name=name, universe="equity_cn", run_dir=str(snapshot), signal_engine_path=str(snapshot / "code/signal_engine.py"),
                signal_definition=None, derived_from=parent))
        provenance = {"session_id": session.session_id, "attempt_id": attempt.attempt_id,
            "artifact_id": identifier, "derived_from": parent, "source_run_id": source.name,
            "snapshot_run_id": new_id, "code_sha256": _run_code_sha256(snapshot)}
        (snapshot / "mona_strategy_creation.json").write_text(json.dumps(provenance, indent=2) + "\n", encoding="utf-8")
        detail = strategy_detail("sdm:" + identifier)
        outputs.append({key: detail[key] for key in ("strategy_id", "version", "name")})
    return outputs


def register_strategy_library(app: FastAPI) -> None:
    def valid_query(request: Request, allowed: set[str]):
        keys = list(request.query_params)
        if set(keys) - allowed or any(len(request.query_params.getlist(key)) != 1 for key in keys):
            raise HTTPException(422, "Invalid strategy query")

    @app.get("/mona/strategy-library", dependencies=[Depends(require_auth)])
    def catalog(request: Request, limit: int = Query(100, ge=1, le=100), offset: int = Query(0, ge=0),
                q: str = Query("", max_length=160), source: str | None = None, market: str = "all"):
        valid_query(request, {"limit", "offset", "q", "source", "market"})
        return strategy_catalog(limit, offset, q, source, market)

    @app.get("/mona/strategy-library/history", dependencies=[Depends(require_auth)])
    def records(request: Request, limit: int = Query(50, ge=1, le=100), offset: int = Query(0, ge=0),
                strategy_id: str | None = None, operation: str | None = None):
        valid_query(request, {"limit", "offset", "strategy_id", "operation"})
        return history(limit, offset, strategy_id, operation)

    @app.get("/mona/strategy-library/{strategy_id}", dependencies=[Depends(require_auth)])
    def detail(strategy_id: str):
        return strategy_detail(strategy_id)
